//! Data-driven per-status body visuals.
//!
//! `archive/data/client/status_visual_effects.ron` maps an `EFST_*` id to a
//! short-lived or persistent **body** visual: a sprite tint (`BodyTint`) or a
//! body alpha (`BodyFade`), a looping STR effect (`LoopingEffect`) or a
//! world-anchored ground ring (`GroundRing`). The renderer for the latter two
//! is the B1 follow-up; the data schema already validates them so rows can be
//! ported without another format change.
//!
//! The file is generated by `tools/gen_status_visuals.py` from the verified
//! status colours and `tools/rustnarok_status_facts.json`; the compiled copy is
//! embedded so an archive override and the fallback cannot drift.

use std::sync::OnceLock;

use korangar_loaders::FileLoader;
use serde::Deserialize;

use crate::graphics::Color;
use crate::loaders::GameFileLoader;

const DATA_PATH: &str = "data\\client\\status_visual_effects.ron";
const FALLBACK: &str = include_str!("../../../archive/data/client/status_visual_effects.ron");

/// Anchor of a looping status effect.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StatusVisualAnchor {
    Body,
    Overhead,
    Ground,
}

/// Body/ground visual of one status effect.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum StatusVisualKind {
    /// Multiply the character sprites by this colour while the status is
    /// active.
    BodyTint {
        tint: Color,
        /// How long the tint is held before it starts fading; `0` keeps it for
        /// the whole status duration.
        hold_ms: u32,
        /// Fade-out time after `hold_ms`; `0` keeps it until the status ends.
        fade_ms: u32,
        /// Higher priority wins when several tinted statuses overlap.
        priority: i16,
    },
    /// Multiply the character alpha while the status is active.
    BodyFade { alpha: f32, fade_in_ms: u32, fade_out_ms: u32 },
    /// Looping `.str` effect that follows the entity while the status is
    /// active (`loop` is always on; the field is kept for data compatibility).
    LoopingEffect {
        file: &'static str,
        anchor: StatusVisualAnchor,
        duration_ms: u32,
        loop_effect: bool,
        tint: Color,
        scale: f32,
    },
    /// World-anchored ring drawn flat below the entity while active.
    GroundRing {
        texture: &'static str,
        radius: f32,
        height: f32,
        duration_ms: u32,
        color: Color,
        pulse: f32,
    },
}

/// One loaded status visual.
#[derive(Debug, Clone, Copy)]
pub struct StatusVisualSpec {
    pub id: u16,
    pub kind: StatusVisualKind,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct StatusVisualFile {
    #[allow(dead_code)]
    provenance: String,
    #[allow(dead_code)]
    version: u32,
    visuals: Vec<StatusVisualRow>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct StatusVisualRow {
    id: u16,
    kind: StatusVisualKindFile,
    source: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
enum StatusVisualKindFile {
    BodyTint {
        tint: (u8, u8, u8),
        #[serde(default)]
        hold_ms: u32,
        #[serde(default)]
        fade_ms: u32,
        #[serde(default)]
        priority: i16,
    },
    BodyFade {
        alpha: f32,
        #[serde(default)]
        fade_in_ms: u32,
        #[serde(default)]
        fade_out_ms: u32,
    },
    LoopingEffect {
        file: String,
        anchor: StatusVisualAnchorFile,
        #[serde(default = "default_duration")]
        duration_ms: u32,
        #[serde(default = "default_true")]
        r#loop: bool,
        #[serde(default)]
        tint: (u8, u8, u8),
        #[serde(default = "default_scale")]
        scale: f32,
    },
    GroundRing {
        texture: String,
        #[serde(default = "default_radius")]
        radius: f32,
        #[serde(default = "default_height")]
        height: f32,
        #[serde(default = "default_duration")]
        duration_ms: u32,
        #[serde(default)]
        color: (u8, u8, u8),
        #[serde(default = "default_pulse")]
        pulse: f32,
    },
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields, rename_all = "PascalCase")]
enum StatusVisualAnchorFile {
    Body,
    Overhead,
    Ground,
}

fn default_duration() -> u32 {
    1_000
}
fn default_true() -> bool {
    true
}
fn default_scale() -> f32 {
    1.0
}
fn default_radius() -> f32 {
    5.0
}
fn default_height() -> f32 {
    0.5
}
fn default_pulse() -> f32 {
    0.0
}

struct StatusVisualTable {
    visuals: Vec<StatusVisualSpec>,
}

fn parse(content: &str) -> Result<StatusVisualTable, String> {
    let file: StatusVisualFile = ron::from_str(content).map_err(|error| format!("schema error: {error}"))?;

    if file.visuals.is_empty() {
        return Err("schema error: no status visuals".to_owned());
    }

    let mut visuals = Vec::with_capacity(file.visuals.len());
    for row in file.visuals {
        if row.source.trim().is_empty() {
            return Err(format!("schema error: status {} has no source", row.id));
        }

        let kind = match row.kind {
            StatusVisualKindFile::BodyTint {
                tint,
                hold_ms,
                fade_ms,
                priority,
            } => {
                if hold_ms > 60_000 || fade_ms > 60_000 {
                    return Err(format!("schema error: status {} tint timing is too large", row.id));
                }
                StatusVisualKind::BodyTint {
                    tint: Color::rgb_u8(tint.0, tint.1, tint.2),
                    hold_ms,
                    fade_ms,
                    priority,
                }
            }
            StatusVisualKindFile::BodyFade {
                alpha,
                fade_in_ms,
                fade_out_ms,
            } => {
                if !(0.0..=1.0).contains(&alpha) || !alpha.is_finite() {
                    return Err(format!("schema error: status {} alpha {} is outside 0..=1", row.id, alpha));
                }
                if fade_in_ms > 60_000 || fade_out_ms > 60_000 {
                    return Err(format!("schema error: status {} alpha timing is too large", row.id));
                }
                StatusVisualKind::BodyFade {
                    alpha,
                    fade_in_ms,
                    fade_out_ms,
                }
            }
            StatusVisualKindFile::LoopingEffect {
                file,
                anchor,
                duration_ms,
                r#loop: loop_effect,
                tint,
                scale,
            } => {
                if !file.ends_with(".str") {
                    return Err(format!("schema error: status {} looping effect must be a .str file", row.id));
                }
                if duration_ms == 0 || duration_ms > 60_000 {
                    return Err(format!("schema error: status {} looping duration is outside 1..=60000", row.id));
                }
                if !scale.is_finite() || !(0.01..=10.0).contains(&scale) {
                    return Err(format!("schema error: status {} looping scale is outside 0.01..=10", row.id));
                }
                StatusVisualKind::LoopingEffect {
                    file: Box::leak(file.into_boxed_str()),
                    anchor: match anchor {
                        StatusVisualAnchorFile::Body => StatusVisualAnchor::Body,
                        StatusVisualAnchorFile::Overhead => StatusVisualAnchor::Overhead,
                        StatusVisualAnchorFile::Ground => StatusVisualAnchor::Ground,
                    },
                    duration_ms,
                    loop_effect,
                    tint: Color::rgb_u8(tint.0, tint.1, tint.2),
                    scale,
                }
            }
            StatusVisualKindFile::GroundRing {
                texture,
                radius,
                height,
                duration_ms,
                color,
                pulse,
            } => {
                if !texture.ends_with(".tga") && !texture.ends_with(".bmp") {
                    return Err(format!(
                        "schema error: status {} ground ring must be a .tga/.bmp texture",
                        row.id
                    ));
                }
                if !radius.is_finite() || !(0.1..=100.0).contains(&radius) {
                    return Err(format!("schema error: status {} ground radius is outside 0.1..=100", row.id));
                }
                if !height.is_finite() || !(0.0..=20.0).contains(&height) {
                    return Err(format!("schema error: status {} ground height is outside 0..=20", row.id));
                }
                if duration_ms == 0 || duration_ms > 60_000 {
                    return Err(format!("schema error: status {} ground duration is outside 1..=60000", row.id));
                }
                if !pulse.is_finite() || !(0.0..=1.0).contains(&pulse) {
                    return Err(format!("schema error: status {} ground pulse is outside 0..=1", row.id));
                }
                StatusVisualKind::GroundRing {
                    texture: Box::leak(texture.into_boxed_str()),
                    radius,
                    height,
                    duration_ms,
                    color: Color::rgb_u8(color.0, color.1, color.2),
                    pulse,
                }
            }
        };

        visuals.push(StatusVisualSpec { id: row.id, kind });
    }

    visuals.sort_by_key(|visual| visual.id);
    if let Some(pair) = visuals.windows(2).find(|pair| pair[0].id == pair[1].id) {
        return Err(format!("schema error: duplicate status visual id {}", pair[0].id));
    }

    Ok(StatusVisualTable { visuals })
}

static COMPILED: OnceLock<StatusVisualTable> = OnceLock::new();
static ARCHIVE: OnceLock<StatusVisualTable> = OnceLock::new();

fn compiled() -> &'static StatusVisualTable {
    COMPILED.get_or_init(|| match parse(FALLBACK) {
        Ok(table) => table,
        Err(error) => {
            crate::logging::log_error!("status visuals: compiled fallback is invalid ({error})");
            StatusVisualTable { visuals: Vec::new() }
        }
    })
}

fn table() -> &'static StatusVisualTable {
    ARCHIVE.get().unwrap_or_else(compiled)
}

/// Loads the status visual table from the client archive (or the compiled
/// fallback) and returns the number of rows.
pub(crate) fn load(game_file_loader: &GameFileLoader) -> usize {
    let from_archive = game_file_loader
        .get(DATA_PATH)
        .ok()
        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned());

    let Some(content) = from_archive.as_deref() else {
        let count = compiled().visuals.len();
        crate::logging::log_debug!("status visuals: loaded {count} rows from the compiled fallback");
        return count;
    };

    match parse(content) {
        Ok(table) => {
            let count = table.visuals.len();
            let _ = ARCHIVE.set(table);
            crate::logging::log_debug!("status visuals: loaded {count} rows from the archive override");
            count
        }
        Err(error) => {
            crate::logging::log_warn!("status visuals: invalid archive override ({error}); using compiled fallback");
            compiled().visuals.len()
        }
    }
}

/// Status visual of one status id, if the data has one.
pub fn status_visual(id: u16) -> Option<&'static StatusVisualSpec> {
    let visuals = &table().visuals;
    visuals
        .binary_search_by_key(&id, |visual| visual.id)
        .ok()
        .map(|index| &visuals[index])
}

/// Validates a status-visual data file and returns its row count.
pub fn validate(content: &str) -> Result<usize, String> {
    parse(content).map(|table| table.visuals.len())
}

/// Validates the compiled fallback.
pub fn validate_compiled() -> Result<usize, String> {
    parse(FALLBACK).map(|table| table.visuals.len())
}

#[cfg(test)]
mod tests {
    use super::{status_visual, validate};
    use crate::graphics::Color;

    #[test]
    fn compiled_status_visuals_are_valid() {
        let count = super::validate_compiled().expect("compiled status visuals");
        assert_eq!(count, 7, "classic body tints plus looping/ground rows");
    }

    #[test]
    fn known_classic_tints_are_present() {
        for id in [2, 8, 23, 26, 86, 132, 147] {
            assert!(status_visual(id).is_some(), "status {id}");
        }
        assert!(status_visual(9999).is_none());
    }

    #[test]
    fn classic_tint_colors_are_preserved() {
        use super::StatusVisualKind;

        for (id, expected) in [
            (23, Color::rgb_u8(255, 115, 115)),
            (147, Color::rgb_u8(255, 115, 115)),
            (86, Color::rgb_u8(255, 191, 191)),
            (132, Color::rgb_u8(250, 120, 120)),
        ] {
            let visual = status_visual(id).expect("classic tint");
            assert!(
                matches!(visual.kind, StatusVisualKind::BodyTint { tint, .. } if tint == expected),
                "status {id}"
            );
        }
    }

    #[test]
    fn body_fade_rows_are_valid() {
        let fade = r#"(
            provenance: "test",
            version: 1,
            visuals: [
                (id: 87, kind: BodyFade(alpha: 0.5, fade_in_ms: 100, fade_out_ms: 200), source: "test"),
            ],
        )"#;
        assert_eq!(validate(fade).unwrap(), 1);
    }

    #[test]
    fn malformed_rows_are_rejected() {
        let malformed = r#"(
            provenance: "test",
            version: 1,
            visuals: [
                (id: 23, kind: BodyFade(alpha: 2.0), source: "test"),
            ],
        )"#;
        assert!(validate(malformed).is_err());
    }

    #[test]
    fn looping_and_ground_rows_are_valid() {
        use super::{StatusVisualAnchor, StatusVisualKind};

        let looping = status_visual(26).expect("Maximize Power looping effect");
        assert!(matches!(
            looping.kind,
            StatusVisualKind::LoopingEffect {
                file,
                anchor: StatusVisualAnchor::Body,
                duration_ms: 1000,
                loop_effect: true,
                ..
            } if file == "effect\\maximizepower.str"
        ));

        let ring = status_visual(8).expect("Quagmire ground ring");
        assert!(matches!(ring.kind, StatusVisualKind::GroundRing {
            radius: 8.0,
            height: 0.5,
            duration_ms: 4000,
            pulse: 0.2,
            ..
        }));
    }

    #[test]
    fn invalid_looping_and_ground_rows_are_rejected() {
        let bad_file = r#"(
            provenance: "test",
            version: 1,
            visuals: [
                (id: 2, kind: LoopingEffect(file: "effect/foo.tga", anchor: Body), source: "test"),
            ],
        )"#;
        assert!(validate(bad_file).is_err());

        let bad_radius = r#"(
            provenance: "test",
            version: 1,
            visuals: [
                (id: 8, kind: GroundRing(texture: "effect/ring_blue.tga", radius: 0.0), source: "test"),
            ],
        )"#;
        assert!(validate(bad_radius).is_err());
    }

    #[test]
    fn duplicate_ids_are_rejected() {
        let duplicate = r#"(
            provenance: "test",
            version: 1,
            visuals: [
                (id: 23, kind: BodyTint(tint: (1, 2, 3)), source: "a"),
                (id: 23, kind: BodyFade(alpha: 0.5), source: "b"),
            ],
        )"#;
        assert!(validate(duplicate).is_err());
    }
}
